Figure 1: Information-criterion model selection on diabetes + 8 noise features (after notebook 08, cell 8). Each curve is an information criterion vs the Lasso penalty α (log scale); lower is better. The dashed verticals mark the minimizing α — AIC ≈ 1.52, BIC ≈ 4.35 (computed, sklearn 1.8.0). BIC’s heavier ln(n)·d penalty pushes its minimum to a larger α, i.e. a simpler model. The criterion curves here are an illustrative convex schematic anchored to the two computed minima, not the notebook’s per-α values.

5. Visualization

famLinear = (getComputedStyle(document.documentElement).getPropertyValue('--family-linear').trim() || "#2E86AB")
classColors = ["#2E86AB", "#06A77D", "#F18F01"]   // 3 blob classes
knnData = {
  function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a&gt;&gt;&gt;15,1|a);t=t+Math.imul(t^t&gt;&gt;&gt;7,61|t)^t;return ((t^t&gt;&gt;&gt;14)&gt;&gt;&gt;0)/4294967296}}
  const r = mulberry32(0);   // deterministic; mirrors the notebook's np.random.seed(0) make_blobs idea
  const gauss = () =&gt; { let u=0,v=0; while(!u)u=r(); while(!v)v=r(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); };
  const centers = [[-3,-2],[3,-1],[0,4]];   // 3 well-separated blob centers
  const pts = [];
  centers.forEach((c, cls) =&gt; {
    for (let i=0;i&lt;26;i++) pts.push({x: c[0]+1.0*gauss(), y: c[1]+1.0*gauss(), cls});
  });
  return pts;
}
knnTest = {
  const xs = knnData.map(d=&gt;d.x), ys = knnData.map(d=&gt;d.y);
  const [xmin,xmax] = [Math.min(...xs), Math.max(...xs)];
  const [ymin,ymax] = [Math.min(...ys), Math.max(...ys)];
  function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a&gt;&gt;&gt;15,1|a);t=t+Math.imul(t^t&gt;&gt;&gt;7,61|t)^t;return ((t^t&gt;&gt;&gt;14)&gt;&gt;&gt;0)/4294967296}}
  const r = mulberry32((Date.now() & 1023));   // new point on reload
  return {x: xmin + r()*(xmax-xmin), y: ymin + r()*(ymax-ymin)};
}
knnVote = {
  const K = 3;
  const withDist = knnData.map((d,i) =&gt; ({...d, i, dist: Math.hypot(d.x-knnTest.x, d.y-knnTest.y)}));
  const nearest = withDist.slice().sort((a,b)=&gt;a.dist-b.dist).slice(0, K);
  const counts = [0,0,0];
  nearest.forEach(d =&gt; counts[d.cls]++);
  const winner = counts.indexOf(Math.max(...counts));
  return {nearest, winner};
}
Plot.plot({
  height: 340, marginLeft: 50, grid: true,
  x: {label: "Feature 1"}, y: {label: "Feature 2"},
  marks: [
    Plot.dot(knnData, {x: "x", y: "y", fill: d =&gt; classColors[d.cls], fillOpacity: 0.55, r: 4}),
    Plot.link(knnVote.nearest, {x1: knnTest.x, y1: knnTest.y, x2: "x", y2: "y", stroke: "#888", strokeDasharray: "3,3"}),
    Plot.dot(knnVote.nearest, {x: "x", y: "y", stroke: "#111", strokeWidth: 1.6, r: 9, fill: "none"}),
    Plot.dot([knnTest], {x: "x", y: "y", fill: classColors[knnVote.winner], stroke: famLinear, strokeWidth: 2, symbol: "star", r: 11})
  ]
})












